```json
{
  "openapi": "3.0.3",
  "info": {
    "title": "Voice assistant: statement and debt services",
    "version": "2026-10-01"
  },
  "servers": [
    { "url": "https://api.freyabank.example/voice/v1/" }
  ],
  "paths": {
    "/cards.list": {
      "post": {
        "summary": "Returns the customer's cards the assistant may talk about (only active cards). Called with the customer number.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "data": {
                    "type": "object",
                    "properties": {
                      "customerNo": { "type": "string", "description": "Customer number handed over by the phone menu, e.g. \"90000001\". May be sent as a string or as a number, both are accepted." },
                      "aiFlow": { "type": "string", "enum": ["CardOps"], "description": "Which use case is asking; for this use case \"CardOps\" (not validated in test)." }
                    },
                    "required": ["customerNo", "aiFlow"]
                  },
                  "call": {
                    "type": "object",
                    "description": "Call metadata logged by the bank; nothing depends on it and the test environment ignores it.",
                    "properties": {
                      "ani": { "type": "string", "description": "Caller's number." },
                      "lang": { "type": "string", "description": "Call language, e.g. \"tr\"." }
                    }
                  }
                },
                "required": ["data"]
              }
            }
          }
        },
        "responses": {
          "200": {
            "description": "Success when result.returnCode is \"1\".",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "data": {
                      "type": "object",
                      "properties": {
                        "cards": {
                          "type": "array",
                          "items": {
                            "type": "object",
                            "properties": {
                              "cardNumber": { "type": "string", "description": "Card number; masked in the test environment (first 6 and last 4 digits visible, e.g. \"540000******1234\"). Send it to the other services exactly as returned here." },
                              "cardNumberLast4": { "type": "string", "description": "Last four digits of the card. Not guaranteed to be unique among the customer's cards." },
                              "productName": { "type": "string", "description": "Card product name, free text from the card system; can be empty." },
                              "status": { "type": "string", "enum": ["A"], "description": "Card status; only active cards (\"A\") come back." },
                              "isMainCard": { "type": "boolean", "description": "false for a card that isn't the customer's own main card." }
                            }
                          }
                        },
                        "validCardsCount": { "type": "integer", "description": "Number of cards returned." },
                        "exitState": { "type": "string", "enum": ["1_CARD", "MULTI_CARD"], "description": "Whether the customer has one card or several." }
                      }
                    },
                    "result": {
                      "type": "object",
                      "properties": {
                        "guid": { "type": "string", "description": "Trace id." },
                        "returnCode": { "type": "string", "description": "\"1\" on success, otherwise the error code (always the same value as code)." },
                        "messageText": { "type": "string", "description": "Message for logs, not to be read to the caller (always the same value as message)." },
                        "code": { "type": "string", "description": "Same value as returnCode." },
                        "message": { "type": "string", "description": "Same value as messageText." },
                        "type": { "type": "string", "nullable": true, "enum": ["ERROR", "WARNING", null], "description": "null on success; \"ERROR\" or \"WARNING\" on errors." },
                        "details": {
                          "type": "object",
                          "properties": {
                            "guid": { "type": "string", "description": "Trace id." },
                            "rootCause": { "type": "string", "nullable": true, "description": "Diagnostic string; log it, don't branch on it." },
                            "errorOrigin": { "type": "string", "nullable": true, "description": "Diagnostic string; log it, don't branch on it." }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          },
          "400": { "description": "INVALID_ARGUMENTS_ERROR (ERROR): a required field is missing or empty. Body has only result, no data." },
          "401": { "description": "Token missing or expired (gateway). Get a new token and retry once." },
          "404": { "description": "FB_IVR_CHANNEL_102 (WARNING): customer has no valid card. Body has only result, no data." },
          "500": { "description": "FBE00099 (ERROR): technical error. Body has only result, no data." }
        }
      }
    },
    "/cards.balance": {
      "post": {
        "summary": "Returns statement and due dates and the debt per currency for one card. Called with the card number.",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "data": {
                    "type": "object",
                    "properties": {
                      "cardNumber": { "type": "string", "description": "Card number exactly as cards.list returned it, e.g. \"540000******1234\"." }
                    },
                    "required": ["cardNumber"]
                  },
                  "call": {
                    "type": "object",
                    "description": "Call metadata logged by the bank; nothing depends on it and the test environment ignores it.",
                    "properties": {
                      "ani": { "type": "string", "description": "Caller's number." },
                      "lang": { "type": "string", "description": "Call language, e.g. \"tr\"." }
                    }
                  }
                },
                "required": ["data"]
              }
            }
          }
        },
